import { useEffect, useState } from "react";
import { toast } from "sonner";
import { Loader2, Maximize2, Minimize2 } from "lucide-react";
import NavBar from "@/components/NavBar";
import { pageEmbedUrl } from "@/lib/api";

export default function EmbedPage({ pageKey, testIdPrefix }) {
  const [loading, setLoading] = useState(false);
  const [immersive, setImmersive] = useState(false);
  const src = pageEmbedUrl(pageKey);

  useEffect(() => {
    const onKey = (e) => e.key === "Escape" && immersive && setImmersive(false);
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [immersive]);

  return (
    <div className="min-h-screen bg-[#fff7f0] flex flex-col">
      {!immersive && (
        <NavBar
          rightSlot={
            <button
              onClick={() => setImmersive(true)}
              data-testid={`${testIdPrefix}-immersive-btn`}
              className="inline-flex items-center gap-1.5 text-xs sm:text-sm font-semibold px-3 py-1.5 rounded-full bg-[#ff6a00] text-white hover:bg-[#e85d00] transition-colors"
              title="Immersive mode (Esc to exit)"
            >
              <Maximize2 size={14} />
              <span className="hidden sm:inline">Immersive</span>
            </button>
          }
        />
      )}

      <main
        className={`flex-1 relative bg-white ${immersive ? "fixed inset-0 z-40" : ""}`}
        data-testid={`${testIdPrefix}-container`}
      >
        {loading ? (
          <div className="absolute inset-0 grid place-items-center">
            <div className="flex items-center gap-3 text-[#5c534d]">
              <Loader2 className="animate-spin text-[#ff6a00]" size={22} />
              <span className="font-medium">Loading…</span>
            </div>
          </div>
        ) : (
          <iframe
            data-testid={`${testIdPrefix}-iframe`}
            title={pageKey}
            src={src}
            className="w-full h-full min-h-[calc(100vh-56px)] border-0 block"
            style={immersive ? { position: "absolute", inset: 0, minHeight: "100vh" } : {}}
            allow="autoplay; fullscreen; clipboard-write; microphone; camera; gamepad; pointer-lock"
          />
        )}
        {immersive && (
          <button
            onClick={() => setImmersive(false)}
            data-testid={`${testIdPrefix}-exit-immersive-btn`}
            className="fixed top-4 right-4 z-50 grid place-items-center w-11 h-11 rounded-full bg-[#ff6a00] text-white shadow-lg hover:bg-[#e85d00] transition-colors"
            title="Exit immersive mode (Esc)"
          >
            <Minimize2 size={18} />
          </button>
        )}
      </main>
    </div>
  );
}
